const body = document.getElementById('demo-body');
const stepCount = document.getElementById('step-count');
let stage = 0;
let cue = 'Put the phone on its charger';
const screens = [
  () => `<div class="screen-eyebrow">YOUR EVENING BOUNDARY</div><div class="phone-symbol" aria-hidden="true">☾</div><h3>You came for a minute.<br>Stay for yourself.</h3><p>Your chosen evening allowance has ended.<br>The coast could use a little light.</p><div class="mini-label">Illustrative limit · Instagram &amp; YouTube</div><button class="phone-action" data-next>Take the quiet way out →</button><button class="secondary-action" data-bypass>Bypass this attempt</button>`,
  () => `<div class="screen-eyebrow">CHOOSE A WIND-DOWN CUE</div><h3>What will you do<br>with the quiet?</h3><p>A small real-world action helps you begin.<br>No photos. No proof required.</p>${[['Put the phone on its charger','↯'],['Stretch beside the bed','⌁'],['Read a page of something','▤']].map(([text,icon])=>`<button class="choice ${cue===text?'active':''}" data-cue="${text}" aria-pressed="${cue===text}">${text}<span aria-hidden="true">${icon}</span></button>`).join('')}<p style="font-size:9px">Rewards depend on time away from chosen feeds,<br>not verification of the action.</p><button class="phone-action" data-next>Preview the quiet window →</button>`,
  () => `<div class="screen-eyebrow">SIMULATED · 5 MINUTES QUIET</div><h3>The first beacon<br>is lit.</h3><div class="progress-ring"><strong>5 / 15</strong><small>quiet minutes</small></div><div class="mini-label">${cue}</div><p>Ten more quiet minutes earn tonight’s chapter.<br>Feeds stay blocked until your morning boundary.</p><p style="font-size:9px">This demo skips time. It does not verify app use.</p><button class="phone-action" data-next>Simulate 15 minutes completed →</button>`,
  () => `<div class="screen-eyebrow">NEXT MORNING · CHAPTER 01</div><h3>A signal found<br>its way home.</h3><div class="postcard"><span aria-hidden="true">✦</span><p>“At 11:19, the radio stirred.<br>Three words through the static:<br><em>We see you.</em>”</p><small>THE FIRST LIGHT / 1 OF 7</small></div><p>Your chapter is safely kept.<br>There’s nothing else to collect today.</p><div class="mini-label">15 quiet minutes · illustrative result</div><button class="phone-action" data-finish>Close the chapter. Go live. ↗</button>`
];
function render(){body.innerHTML=screens[stage]();stepCount.textContent=`0${stage+1} / 04`;body.style.animation='none';void body.offsetWidth;body.style.animation='';}
body.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.hasAttribute('data-next')){stage=Math.min(stage+1,3);render();}else if(target.dataset.cue){cue=target.dataset.cue;render();}else if(target.hasAttribute('data-bypass')){body.innerHTML='<div class="screen-eyebrow">AN INTENTIONAL CHOICE</div><div class="phone-symbol" aria-hidden="true">⌁</div><h3>Another evening.<br>Another chance.</h3><p>In the proposed app, bypassing stops this attempt and releases its shields. Your earlier chapters stay yours.</p><p>This browser demo has no app restrictions to release.</p><button class="phone-action" data-restart>Try the quiet route again →</button>';stepCount.textContent='BYPASS';}else if(target.hasAttribute('data-finish')){body.innerHTML='<div class="screen-eyebrow">THE CHAPTER IS CLOSED</div><div class="phone-symbol" aria-hidden="true">☼</div><h3>Your day<br>is yours.</h3><p>A good reward should give you a stopping point.<br>That’s the end of this walkthrough.</p><button class="phone-action" data-restart>Replay the concept →</button>';stepCount.textContent='COMPLETE';}else if(target.hasAttribute('data-restart')){stage=0;render();}});
document.getElementById('reset').addEventListener('click',()=>{stage=0;cue='Put the phone on its charger';render();});
async function shareConcept(){const url=location.origin+location.pathname;const status=document.getElementById('share-status');try{if(navigator.share){await navigator.share({title:'Lastlight — a quieter kind of game',text:'A lighthouse mystery that advances when you step away from bedtime scrolling. Explore the concept and MVP.',url});status.textContent='';}else{await navigator.clipboard.writeText(url);status.textContent='Link copied. Ready to share.';document.getElementById('share').textContent='Link copied ✓';setTimeout(()=>{document.getElementById('share').innerHTML='Share concept <span aria-hidden="true">↗</span>';},2500);}}catch(error){if(error.name!=='AbortError'){status.textContent='Copy this link: '+url;status.scrollIntoView({block:'center',behavior:'smooth'});}}}
document.getElementById('share').addEventListener('click',shareConcept);document.getElementById('share-bottom').addEventListener('click',shareConcept);render();
fetch('downloads/release.json').then(response=>{if(!response.ok)throw new Error('No release');return response.json()}).then(release=>{document.getElementById('apk-meta').textContent=`Version ${release.version} · ${(release.bytes/1024/1024).toFixed(1)} MB · Android ${release.minAndroid}+ · ${release.architecture}`;document.getElementById('apk-checksum').textContent=release.variants.map(variant=>variant.architecture+' SHA-256: '+variant.sha256).join(' | ');}).catch(()=>{document.getElementById('apk-meta').textContent='Android early access · Release details unavailable';});
